import { randomUUID } from "node:crypto";
import { chmodSync, closeSync, constants, fchmodSync, lstatSync, mkdirSync, openSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

import { migrateDataDirectory } from "./data-migration.js";

const MAX_CONFIG_BYTES = 16 * 1024;
const PRIVATE_DIRECTORY_MODE = 0o700;

/** Marks agent files Useful Skills generated and may overwrite; it opens the first frontmatter line of a generated file. */
export const GENERATED_MARKER = "# Generated by Useful Skills";

const GENERATED_HEADER = new RegExp(`^---\\r?\\n${GENERATED_MARKER} `);

/**
 * True when agent text is one Useful Skills generated: the marker opens the line right after the opening `---`.
 * The marker text anywhere else, such as in a user's agent body, does not make the file ours to overwrite.
 */
export function isGeneratedAgent(text) {
  return GENERATED_HEADER.test(text);
}

/** Plugin agent -> model role, matching OMP's task.agentModelOverrides. */
export const ROLE_AGENTS = Object.freeze({
  planner: "plan",
  scout: "research",
  frontend: "frontend",
  backend: "backend",
  "general-purpose": "implementation",
  reviewer: "review",
  "security-reviewer": "security",
  "release-assessor": "assess",
});

export const ROLES = Object.freeze(["research", "frontend", "backend", "implementation", "review", "security", "plan", "assess", "default"]);

/** Roles whose missing row inherits the host's session model instead of using `default`. */
export const INHERIT_WHEN_ABSENT = Object.freeze(new Set(["assess"]));

/** The selection for a role: its own row, else `fallback` for an inherit-when-absent role, else `default`, else `fallback`. */
export function roleSelection(roles, role, fallback) {
  if (Object.hasOwn(roles, role)) {
    return roles[role];
  }

  if (INHERIT_WHEN_ABSENT.has(role)) {
    return fallback;
  }

  return roles.default ?? fallback;
}

/**
 * A strict YAML subset: comments, a `modelRoles:` key, and indented `role: selector` rows.
 * `parseSelector(role, raw)` is the host's selector syntax; it returns the selection or throws a message naming the role.
 */
export function parseModelsConfig(text, parseSelector) {
  const roles = {};
  let inRoles = false;
  for (const [index, row] of text.split(/\r?\n/).entries()) {
    const line = row.replace(/\s+#.*$/, "").trimEnd();
    if (!line.trim() || line.trimStart().startsWith("#")) continue;
    if (line === "modelRoles:") {
      inRoles = true;
      continue;
    }
    const entry = /^\s+([a-z]+):\s*(["']?)([^"'\s]+)\2$/.exec(line);
    if (!inRoles || !entry) {
      throw new Error(`Unsupported content on line ${index + 1}; expected \`modelRoles:\` followed by indented \`role: selector\` rows.`);
    }
    const [, role, , selector] = entry;
    if (!ROLES.includes(role)) {
      throw new Error(`Unknown role "${role}" on line ${index + 1}. Known roles: ${ROLES.join(", ")}.`);
    }
    if (Object.hasOwn(roles, role)) {
      throw new Error(`Role "${role}" is defined more than once.`);
    }
    roles[role] = parseSelector(role, selector);
  }
  if (!inRoles) {
    throw new Error("Missing `modelRoles:` section.");
  }
  return roles;
}

/** The role catalogue the desktop reads from `<data dir>/roles.json`. */
export function roleCatalogueText() {
  return `${JSON.stringify({
    version: 1,
    roles: ROLES.filter(role => role !== "default"),
    agents: ROLE_AGENTS,
    inheritWhenAbsent: [...INHERIT_WHEN_ABSENT],
  }, null, 2)}\n`;
}

/**
 * Publish the role catalogue in an existing data directory; rewritten only when its content changes.
 * Best effort: an unwritable directory must not break a session start. Returns true when the file was written.
 */
export function writeRoleCatalogue(dataDir) {
  try {
    if (!lstatSync(dataDir, { throwIfNoEntry: false })?.isDirectory()) return false;
    const file = path.join(dataDir, "roles.json");
    const text = roleCatalogueText();
    if (readOptional(file) === text) return false;
    writeAtomic(file, text);
    return true;
  } catch {
    return false;
  }
}

/** The Useful Skills version from the package.json beside this module, or undefined when the bundle has none. */
function skillsVersion() {
  try {
    const version = JSON.parse(readFileSync(new URL("./package.json", import.meta.url), "utf8")).version;
    return typeof version === "string" && /^\d+\.\d+\.\d+/.test(version) ? version : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Roles of ROLES that a parsed config does not list and that need a row. A role that falls back to a `default` row the
 * file has is left out: that is how the file chooses it. A role that inherits when absent always gets a row.
 */
export function missingRoles(roles) {
  return ROLES.filter(role => !Object.hasOwn(roles, role) && (INHERIT_WHEN_ABSENT.has(role) || !Object.hasOwn(roles, "default")));
}

/**
 * Append rows for `missing` roles at the end of the `modelRoles:` block, after a comment line. Every existing line
 * is kept as is. `defaultFor(role)` is the selector text of a row. `version` null omits the version. Expects text that already parsed.
 */
export function appendRoles(text, missing, defaultFor, version = skillsVersion()) {
  version ||= undefined;
  const newline = text.includes("\r\n") ? "\r\n" : "\n";
  const lines = text.split(/\r?\n/);
  const trailing = lines.at(-1) === "" ? lines.pop() : undefined;
  let at = lines.findLastIndex(row => /^\s+[a-z]+:\s/.test(row) && !row.trimStart().startsWith("#"));
  if (at < 0) at = lines.indexOf("modelRoles:");
  const added = [
    `# Added by Useful Skills${version ? ` ${version}` : ""}: ${missing.join(", ")}`,
    ...missing.map(role => `  ${role}: ${defaultFor(role)}`),
  ];
  lines.splice(at + 1, 0, ...added);
  return lines.join(newline) + (trailing === undefined ? "" : newline);
}

/** Read a model config, refusing one larger than 16 KiB. */
export function readConfigText(file) {
  const text = readFileSync(file, "utf8");
  if (Buffer.byteLength(text) > MAX_CONFIG_BYTES) {
    throw new Error("Model configuration exceeds 16 KiB.");
  }
  return text;
}

/**
 * The workflow settings store requires `<configDir>/harness-useful-skills` to be private, so create it
 * owner-only and tighten an existing real directory. Best effort: a symlink, non-directory, or
 * permission failure is left for the store to report instead of failing session start here.
 */
export function ensurePrivateDirectory(directory) {
  try {
    mkdirSync(path.dirname(directory), { recursive: true });
    mkdirSync(directory, { mode: PRIVATE_DIRECTORY_MODE });
  } catch {
    // Already present, or unwritable; the checks below and later writes decide what happens.
  }

  let descriptor;
  try {
    if (!lstatSync(directory).isDirectory()) {
      return;
    }

    // Open the directory itself, not a symlink destination, before changing its permissions.
    descriptor = openSync(directory, constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW);
    fchmodSync(descriptor, PRIVATE_DIRECTORY_MODE);
  } catch {
    // Missing, replaced, or not ours to change; the settings store reports the resulting state.
  } finally {
    if (descriptor !== undefined) {
      closeSync(descriptor);
    }
  }
}

/** Replace a file through a uniquely named temporary file so readers never see partial text. */
export function writeAtomic(file, text, mode = 0o644) {
  mkdirSync(path.dirname(file), { recursive: true });
  const temporary = `${file}.${randomUUID()}.tmp`;
  try {
    writeFileSync(temporary, text, { flag: "wx", mode });
    // The umask can only narrow the mode the file was created with; set the exact one before the rename publishes it.
    chmodSync(temporary, mode);
    renameSync(temporary, file);
  } finally {
    rmSync(temporary, { force: true });
  }
}

/** File text, or undefined when the file does not exist. */
export function readOptional(file) {
  try {
    return readFileSync(file, "utf8");
  } catch (error) {
    if (error?.code === "ENOENT") return undefined;
    throw error;
  }
}

/**
 * Create the model config on first use and regenerate the host's role agents from it.
 * Never overwrites an agent file that Useful Skills did not generate (see isGeneratedAgent).
 *
 * - `configFile`: the models.yml path, inside the host's data directory; that directory is made private, and a
 *   data directory saved under the name used before the rename is moved to it first.
 * - `agentFile(agent)`: where the generated agent for a plugin agent name lives.
 * - `defaultConfig`: text written when `configFile` does not exist.
 * - `defaultRole(role)`: optional; the host's default selector text. An existing config that parses gets rows for
 *   roles it lacks appended (see appendRoles) and the result lists them in `added`.
 * - `parseSelector(role, raw)`: the host's selector syntax (see parseModelsConfig).
 * - `render(agent, selection)`: the full generated agent text.
 * - `fallback`: the selection when neither the agent's role nor `default` is configured, and for a role in
 *   INHERIT_WHEN_ABSENT whose row is missing.
 *
 * Returns `{ configFile, created, added, agents }` where each agent maps to `{ state, file, selection }` and state is
 * created, updated, ready, or conflict; an invalid config instead returns `{ configFile, created, error, agents: {} }`.
 */
export function syncRoleAgents({ configFile, agentFile, defaultConfig, defaultRole, parseSelector, render, fallback }) {
  migrateDataDirectory(path.dirname(path.dirname(configFile)));
  ensurePrivateDirectory(path.dirname(configFile));

  let created = false;
  if (readOptional(configFile) === undefined) {
    writeAtomic(configFile, defaultConfig);
    created = true;
  }

  let roles;
  let added = [];
  try {
    const text = readConfigText(configFile);
    roles = parseModelsConfig(text, parseSelector);
    const missing = defaultRole && !created ? missingRoles(roles) : [];
    if (missing.length) {
      const next = appendRoles(text, missing, defaultRole);
      roles = parseModelsConfig(next, parseSelector);
      writeAtomic(configFile, next);
      added = missing;
    }
  } catch (error) {
    return { configFile, created, error: error.message, agents: {} };
  }
  writeRoleCatalogue(path.dirname(configFile));

  const agents = {};
  for (const [agent, role] of Object.entries(ROLE_AGENTS)) {
    const file = agentFile(agent);
    const selection = roleSelection(roles, role, fallback);
    const existing = readOptional(file);
    if (existing !== undefined && !isGeneratedAgent(existing)) {
      agents[agent] = { state: "conflict", file, selection };
      continue;
    }

    const next = render(agent, selection);
    if (existing === next) {
      agents[agent] = { state: "ready", file, selection };
    } else {
      writeAtomic(file, next);
      agents[agent] = { state: existing === undefined ? "created" : "updated", file, selection };
    }
  }
  return { configFile, created, added, agents };
}
